const input=$json;
const s=input.snapshot ?? {};
const findings=[];

function add(kind,item,priority,reasonCode,message){
  const ref=item?.id ?? item?.customer_event_id ?? item?.source_event_id ?? item?.card_id ?? item?.key ?? 'unknown';
  findings.push({
    kind,
    priority,
    reason_code:reasonCode,
    customer_event_id:item?.customer_event_id ?? null,
    source_ref:String(ref),
    message,
    context:item ?? {},
    dedupe_key:'watchdog:'+kind+':'+String(ref),
    auto_correction_allowed:false
  });
}

for(const item of (s.overdue_followups ?? [])){
  add('followup_overdue',item,'high','FOLLOWUP_OVERDUE','Follow-up automático pendente está vencido.');
}
for(const item of (s.impossible_states ?? [])){
  add('impossible_state',item,'critical','IMPOSSIBLE_STATE','Combinação de estados viola a máquina canônica.');
}
for(const item of (s.signed_payment_inconsistencies ?? [])){
  add('signed_payment_inconsistent',item,'critical','SIGNED_PAYMENT_STATE_INCOHERENT','Contrato assinado sem estado financeiro coerente.');
}
for(const item of (s.invalid_wins ?? [])){
  add('invalid_win',item,'critical','GANHO_WITHOUT_CRITERIA','Evento em GANHO sem contrato assinado + pagamento verificado.');
}
for(const item of (s.upcoming_logistics_blocked ?? [])){
  const days=Number(item?.days_until_event);
  const priority=Number.isFinite(days) && days<=2 ? 'critical' : 'high';
  add('logistics_blocked_near_event',item,priority,'LOGISTICS_BLOCKED_NEAR_EVENT','Evento próximo permanece com logística bloqueada.');
}
for(const item of (s.delayed_deliveries ?? [])){
  add('delivery_overdue',item,'high','DELIVERY_OVERDUE','Entrega pós-evento excedeu o SLA esperado.');
}
for(const item of (s.projection_drifts ?? [])){
  const priority=item?.drift_status==='error' ? 'high' : 'normal';
  add('projection_drift',item,priority,'TRELLO_PROJECTION_DRIFT','Projeção Trello diverge do estado canônico.');
}
for(const item of (s.open_dead_letters ?? [])){
  add('dead_letter',item,'high','DEAD_LETTER_OPEN','Evento esgotou retries e requer resolução controlada.');
}
for(const item of (s.duplicate_campaign_members ?? [])){
  add('campaign_member_duplicate',item,'high','CAMPAIGN_MEMBER_DUPLICATE','Campanha contém membro duplicado para o mesmo evento.');
}
for(const item of (s.recurring_state_version_conflicts ?? [])){
  add('state_version_conflict_recurring',item,'high','STATE_VERSION_CONFLICT_RECURRING','Conflitos recorrentes de versão indicam concorrência ou adapter incorreto.');
}

const rank={critical:4,high:3,normal:2,low:1};
findings.sort((a,b)=>(rank[b.priority]??0)-(rank[a.priority]??0)||a.kind.localeCompare(b.kind));

const operations=findings.map((finding)=>({
  action:'CREATE_HUMAN_TASK',
  customer_event_id:finding.customer_event_id,
  task_type:'audit_watchdog',
  priority:finding.priority,
  reason_code:finding.reason_code,
  payload:{
    dedupe_key:finding.dedupe_key,
    kind:finding.kind,
    source_ref:finding.source_ref,
    message:finding.message,
    context:finding.context,
    auto_correction_allowed:false
  }
}));

const counts={critical:0,high:0,normal:0,low:0,total:findings.length};
for(const f of findings) counts[f.priority]=(counts[f.priority]??0)+1;

return {json:{
  status:findings.length?'findings':'clean',
  evaluated_at:input.now ?? null,
  counts,
  findings,
  operations,
  auto_corrections:[],
  blockers:[]
}};
